from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, Field, ValidationError, condecimal, conint, validator


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0, max_digits=20, decimal_places=2)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal with 2 decimals exactly
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        # Quantize to 2 decimal places, rounding down to avoid rounding surprises
        d = d.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    class Config:
        # No orm_mode needed here
        arbitrary_types_allowed = True

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API.
    Output JSON includes "number", "issued_at" formatted as YYYY-MM-DDTHH:MM:SSZ in UTC,
    "lines" with "sku", "quantity", "unit_price" as string with 2 decimals,
    and "total" as string with 2 decimals.
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Compute total as Decimal sum of quantity * unit_price
    total = sum((line.quantity * line.unit_price for line in invoice.lines), Decimal("0.00"))
    # Format total as string with exactly two decimals
    total_str = f"{total:.2f}"

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with 2 decimals
    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": f"{line.unit_price:.2f}",
        })

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Return JSON text
    import json
    return json.dumps(out, separators=(",", ":"))

from pydantic import BaseModel, Field, root_validator, validator, ValidationError
import re


class SignupPayload(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email")
    def email_must_contain_at(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @validator("phone")
    def normalize_phone(cls, v: str) -> str:
        if not isinstance(v, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", v)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def passwords_match(cls, values):
        pw = values.get("password")
        pwc = values.get("password_confirm")
        if pw is not None and pwc is not None and pw != pwc:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload dict using pydantic.

    Returns a dict with keys: username, email (stripped and lowercased), phone (compact form).
    Raises ValueError (ValidationError) on invalid or missing fields.
    """
    validated = SignupPayload.parse_obj(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import List, Union

from pydantic import BaseModel, field_validator, ValidationError


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    model_config = {
        "from_attributes": False,
    }

    @field_validator("quantity")
    @classmethod
    def check_quantity(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @field_validator("unit_price", mode="before")
    @classmethod
    def coerce_unit_price(cls, v: Union[str, int, float, Decimal]) -> Decimal:
        try:
            d = Decimal(str(v))
        except (InvalidOperation, ValueError):
            raise ValueError("unit_price must be a decimal number")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    model_config = {
        "from_attributes": False,
    }

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v: Union[str, datetime]) -> datetime:
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except ValueError:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        # Make naive datetimes UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for billing API.
    Raises ValueError on invalid input.
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Format issued_at as "YYYY-MM-DDTHH:MM:SSZ" in UTC
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Format lines with unit_price as string with two decimals
    lines_out = []
    total = Decimal("0")
    for line in invoice.lines:
        line_total = line.unit_price * line.quantity
        total += line_total
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": f"{line.unit_price:.2f}",
            }
        )

    total_str = f"{total:.2f}"

    import json

    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }
    return json.dumps(out, separators=(",", ":"))

from profile_models import load_profile


def import_profiles(rows: list) -> list:
    """Validate profile rows and return valid ones as dicts, skipping invalid rows silently."""
    valid_profiles = []
    for row in rows:
        try:
            profile = load_profile(row)
        except Exception:
            # Silently skip invalid rows (validation errors or type errors)
            continue
        # Return dict with required keys and optional bio, excluding fields not requested
        # The profile has tags and website fields but we exclude them by only selecting needed keys
        valid_profiles.append({
            "user_id": profile.user_id,
            "display_name": profile.display_name,
            "bio": profile.bio,
            "zip_code": profile.zip_code,
        })
    return valid_profiles

import re
from pydantic import BaseModel, Field, field_validator, ValidationError


class SignupModel(BaseModel):
    username: str = Field(...)
    email: str = Field(...)
    phone: str = Field(...)
    password: str = Field(...)
    password_confirm: str = Field(...)

    model_config = {
        "extra": "forbid",
    }

    _username_re = re.compile(r"^[a-z0-9_]{3,20}$")

    @field_validator("username")
    @classmethod
    def validate_username(cls, v: str) -> str:
        if not cls._username_re.fullmatch(v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @field_validator("phone")
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r"[ \.\-\(\)]", "", v)
        if not re.fullmatch(r"\+[0-9]{8,15}", compact):
            raise ValueError("phone must be '+' followed by 8-15 digits after removing spaces, dots, dashes, parentheses")
        return compact

    @field_validator("password_confirm")
    @classmethod
    def validate_password_confirm(cls, v: str, info) -> str:
        # info.data contains all fields validated so far
        password = info.data.get("password")
        if password is None:
            # password validation will catch missing password
            return v
        if v != password:
            raise ValueError("password_confirm must equal password")
        return v

    @field_validator("password")
    @classmethod
    def validate_password(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload dict with fields:
    - username: ^[a-z0-9_]{3,20}$
    - email: contains '@', returned stripped and lowercased
    - phone: spaces, dots, dashes, parentheses removed, then '+' followed by 8-15 digits
    - password: at least 8 characters
    - password_confirm: must equal password

    Returns dict with keys: username, email, phone (compact phone).
    Raises pydantic ValidationError (ValueError) for missing or invalid fields.
    """
    validated = SignupModel.model_validate(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }
